function clean(s){return String(s||"").split(/[\\/]/).pop().replace(/\.(nes|zip|sfc|smc|gba|bin|md|gen|smd|sms|gg|chd|pbp|iso)$/i,"").replace(/\s*(\((?:(?:USA|Europe|Japan|World|Russia|Asia|Australia|Brazil|Canada|Korea|China|Germany|France|Spain|Italy|Sweden|U|E|J|W)(?:\s*,\s*(?:USA|Europe|Japan|World|Russia|Asia|Australia|Brazil|Canada|Korea|China|Germany|France|Spain|Italy|Sweden|U|E|J|W))*|Unl|Rev[^)]*|PRG[^)]*|En(?:,[A-Za-z]+)*|[A-Z]{2,3})\)|\[(?:!|[a-zA-Z][^\]]*|[0-9]+)\])\s*$/g,"").trim()}
function title(s){let a=String(s||"");for(let i=0;i<12;i++){const b=clean(a);if(a===b)break;a=b}return a.replace(/_/g," ").trim()||"Без названия"}
function norm(s){return title(s).normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/&/g," and ").replace(/[’'‘]/g,"").replace(/[^\p{L}\p{N}]+/gu," ").trim()}
